<style>
  :root {
    /* Biolinx Labs brand tokens, pulled from biolinxlabs.com */
    --background: #ffffff;
    --foreground: #171717;
    --card: #ffffff;
    --muted-foreground: #525252;
    --secondary: #f4f9fd;
    --primary-foreground: #ffffff;
    --border: #e5e5e5;
    --input: #d4d4d4;
    --destructive: #dc2626;

    /* Blue palette, built from the site accent #1d9bf0 */
    --brand: #1d9bf0;
    --brand-strong: #1478bd;
    --brand-soft: #eaf5fe;
    --brand-tint: #9fd4f8;
    --banner: #eaf5fe;
    --banner-border: #b9e0fb;
    --topbar: #171717;
    --topbar-foreground: #ffffff;
    --highlight: #d3ebfd;
    --link: #1478bd;
  }

  body { background-color: var(--background); color: var(--foreground); font-family: 'Montserrat', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif; }
  h1, h2, .font-display { font-family: 'Montserrat', ui-sans-serif, system-ui, sans-serif; }

  .highlight-mark { background-color: var(--highlight); }
  .cta-btn {
    display: block; width: 100%; border-radius: 0.375rem;
    background-color: var(--brand); padding: 0.85rem 1rem; text-align: center;
    color: white; font-family: 'Montserrat', sans-serif; font-weight: 700;
    box-shadow: 0 3px 0 0 var(--brand-strong); transition: background-color 150ms ease;
  }
  .cta-btn:hover { background-color: var(--brand-strong); }

  .timer-box {
    width: 54px; border-radius: 0.375rem; background-color: var(--foreground);
    color: var(--background); padding: 0.5rem; text-align: center;
  }

  .page-grid {
    display: grid;
    grid-template-columns: 1fr;
  }
  @media (min-width: 1024px) {
    .page-grid { grid-template-columns: minmax(0, 1fr) 300px; }
  }

  /* Top bar brand lockup */
  .topbar-inner { display: flex; align-items: center; gap: 10px; }
  .topbar-logo { height: 30px; width: 30px; border-radius: 6px; object-fit: contain; background: #fff; }
  .topbar-divider { width: 1px; height: 18px; background: rgba(255,255,255,0.25); }

  /* Hero: one editorial product image, whole vial contained on a lit plinth, never cropped */
  .hero-card { border: 1px solid var(--banner-border); border-radius: 8px; background: var(--brand-soft); overflow: hidden; }
  .hero-figure { padding: 22px 18px 16px; }
  .hero-plinth { display: flex; align-items: center; justify-content: center; background: radial-gradient(ellipse at 50% 42%, #ffffff 0%, #ffffff 55%, #f2f8fd 100%); border: 1px solid var(--banner-border); border-radius: 8px; padding: 22px; }
  .hero-plinth img { width: auto; max-width: 100%; max-height: 400px; height: auto; display: block; margin: 0 auto; object-fit: contain; }
  .hero-note { margin-top: 14px; text-align: center; font-size: 14px; line-height: 20px; color: var(--muted-foreground); }
  .hero-caption { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 10px 22px; padding: 14px 18px 18px; border-top: 1px solid var(--banner-border); }
  .hero-badge { display: flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: var(--brand-strong); }
  .hero-badge img { height: 26px; width: 26px; display: block; }
  @media (max-width: 480px) { .hero-badge { font-size: 11px; } .hero-badge img { height: 22px; width: 22px; } .hero-plinth img { max-height: 300px; } }

  /* Product images are editorial links, not widgets. Lift + glow on hover and keyboard focus. */
  .img-link { display: block; border-radius: 8px; transition: transform 200ms ease, box-shadow 200ms ease; }
  .img-link:hover, .img-link:focus-visible { transform: translateY(-3px); box-shadow: 0 10px 26px rgba(29,155,240,0.26); }
  .img-link:focus-visible { outline: 2px solid var(--brand); outline-offset: 3px; }
  @media (prefers-reduced-motion: reduce) {
    .img-link { transition: none; }
    .img-link:hover, .img-link:focus-visible { transform: none; }
  }

  /* Final CTA offer box */
  .offer-box { border-radius: 20px; overflow: hidden; background: var(--brand-soft); border: 1px solid var(--banner-border); box-shadow: 0 2px 13px rgba(0,0,0,0.06); }
  .offer-grid { display: grid; grid-template-columns: 1fr; }
  @media (min-width: 768px) { .offer-grid { grid-template-columns: 1fr 1fr; } }
  .offer-copy { padding: 28px 20px; }
  @media (min-width: 768px) { .offer-copy { padding: 36px 28px; } }
  .offer-badge { display: inline-flex; align-items: center; gap: 8px; border: 1.5px solid var(--brand); border-radius: 999px; padding: 5px 12px; margin-bottom: 14px; }
  .offer-badge span { font-size: 12px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: var(--brand-strong); }
  .offer-badge svg { color: var(--brand-strong); }
  .offer-heading { font-family: 'Montserrat', sans-serif; font-size: 30px; line-height: 36px; font-weight: 700; margin: 0; color: var(--foreground); }
  .offer-body { margin-top: 10px; font-size: 16px; line-height: 22.4px; color: var(--muted-foreground); }
  .offer-body strong { color: var(--foreground); }
  .offer-steps { margin-top: 22px; display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; padding-top: 18px; border-top: 1px solid var(--banner-border); }
  .offer-step { display: flex; flex-direction: column; align-items: center; text-align: center; }
  .offer-step-icon { position: relative; display: flex; height: 40px; width: 40px; align-items: center; justify-content: center; border-radius: 999px; border: 1.5px solid var(--brand); color: var(--brand-strong); background: var(--background); }
  .offer-step-num { position: absolute; top: -6px; left: -6px; display: flex; height: 18px; width: 18px; align-items: center; justify-content: center; border-radius: 999px; background: var(--brand); font-size: 10px; font-weight: 700; color: #fff; }
  .offer-step-title { margin-top: 8px; font-size: 12px; font-weight: 700; line-height: 16px; }
  .offer-step-sub { font-size: 11px; line-height: 15px; color: var(--muted-foreground); }
  .offer-note { margin-top: 16px; display: flex; gap: 12px; align-items: flex-start; border-radius: 10px; border: 1px solid var(--banner-border); background: var(--background); padding: 12px 14px; }
  .offer-note p { margin: 0; font-size: 14px; line-height: 20px; color: var(--muted-foreground); }
  .offer-note p strong { color: var(--foreground); }
  .offer-note-title { font-weight: 700; color: var(--foreground); display: block; }
  .offer-media { position: relative; min-height: 240px; background: #fff; display: flex; align-items: center; justify-content: center; padding: 20px; }
  .offer-media img { width: 100%; height: auto; max-height: 420px; display: block; object-fit: contain; }

  /* Comment thread, text only */
  .cmt-name { font-weight: 600; color: var(--link); }
  .cmt-tag { display: inline-block; margin-left: 8px; font-size: 11px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; color: var(--brand-strong); background: var(--brand-soft); border: 1px solid var(--banner-border); border-radius: 999px; padding: 1px 8px; vertical-align: middle; }

  /* Mobile-only fixed bottom bar */
  .mobile-sticky-bar {
    display: none;
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 40;
    background: var(--background); border-top: 1px solid var(--border);
    box-shadow: 0 -4px 16px rgba(0,0,0,0.08);
    padding: 10px 14px;
  }
  .mobile-sticky-bar .msb-btn {
    display: flex; align-items: center; justify-content: center; gap: 8px;
    width: 100%; text-align: center;
    border-radius: 0.375rem; background-color: var(--brand); color: #fff;
    font-family: 'Montserrat', sans-serif; font-weight: 700; font-size: 15px;
    padding: 12px 14px; box-shadow: 0 3px 0 0 var(--brand-strong);
  }
  .mobile-sticky-bar .msb-btn svg { flex-shrink: 0; }
  body { padding-bottom: 0; }
  @media (max-width: 1023px) {
    .mobile-sticky-bar { display: block; }
    body { padding-bottom: 60px; }
  }
</style>
</head>
